type Key =
  | Digit(d: Int)
  | Enter
  | Clear

fn door_lock(code: String, events: List[Key]) -> String {
  var state = "locked"
  var buf = ""
  var fails = 0
  let size = str_len(code)
  for k in events {
    if state == "open" {
      if k == Enter {
        state = "locked"
        buf = ""
      }
    } else if state == "locked" {
      match k {
        Digit(d) => {
          buf = buf + to_string(d)
          if str_len(buf) > size {
            buf = buf
              |> split("")
              |> drop(str_len(buf) - size)
              |> join("")
          }
        },
        Clear => buf = "",
        Enter => {
          if buf == code {
            state = "open"
            fails = 0
          } else {
            fails = fails + 1
            if fails > 3 {
              state = "blocked"
            }
          }
          buf = ""
        },
      }
    }
  }
  return state
}

