    """Flatten a textual nested integer list and report its maximum depth."""
    parser = _Parser(s.replace(" ", ""))
    try:
        parser.parse()
    except _Invalid as exc:
        return {"ok": False, "error": str(exc)}
    return {"ok": True, "value": (parser.values, parser.max_depth)}

