export function heading_numbers(lines: string[]): string[] {
  const counters = [0, 0, 0];
  const out: string[] = [];
  for (const line of lines) {
    const m = /^(#{1,3}) (.+)$/.exec(line);
    if (!m) continue;
    const level = m[1].length - 1;
    counters[level]++;
    for (let i = level + 1; i < 3; i++) counters[i] = 0;
    out.push((counters[0] + 1) + (counters[1] ? "." + counters[1] : "") + (counters[2] ? "." + counters[2] : "") + " " + m[2]);
  }
  return out;
}

